/**
  * @brief  Draw a bitmap on LCD.
  * @param  Instance LCD Instance.
  * @param  Xpos X position.
  * @param  Ypos Y position.
  * @param  pBmp Pointer to bitmap.
  * @retval BSP status.
  */
int32_t BSP_LCD_DrawBitmap(uint32_t Instance, uint32_t Xpos, uint32_t Ypos, uint8_t *pBmp)
{
  int32_t  status = BSP_ERROR_NONE;
  uint32_t index;
  uint32_t width;
  uint32_t height;
  uint32_t bit_pixel;
  uint32_t Address;
  uint32_t InputColorMode;
  uint8_t *pbmp_tmp;

  if (Instance >= LCD_INSTANCES_NBR)
  {
    status = BSP_ERROR_WRONG_PARAM;
  }
  else
  {
    /* Get bitmap data address offset */
    index = (uint32_t)pBmp[10] + ((uint32_t)pBmp[11] << 8) + ((uint32_t)pBmp[12] << 16)  + ((uint32_t)pBmp[13] << 24);

    /* Read bitmap width */
    width = (uint32_t)pBmp[18] + ((uint32_t)pBmp[19] << 8) + ((uint32_t)pBmp[20] << 16)  + ((uint32_t)pBmp[21] << 24);

    /* Read bitmap height */
    height = (uint32_t)pBmp[22] + ((uint32_t)pBmp[23] << 8) + ((uint32_t)pBmp[24] << 16)  + ((uint32_t)pBmp[25] << 24);

    /* Read bit/pixel */
    bit_pixel = (uint32_t)pBmp[28] + ((uint32_t)pBmp[29] << 8);

    /* Set the address */
    Address = (hlcd_ltdc.LayerCfg[0].FBStartAdress + (4U * ((Ypos * PIXEL_PER_LINE) + Xpos)));

    /* Get the layer pixel format */
    if ((bit_pixel / 8U) == 4U)
    {
      InputColorMode = DMA2D_INPUT_ARGB8888;
    }
    else if ((bit_pixel / 8U) == 2U)
    {
      InputColorMode = DMA2D_INPUT_RGB565;
    }
    else
    {
      InputColorMode = DMA2D_INPUT_RGB888;
    }

    /* Bypass the bitmap header */
    pbmp_tmp = pBmp + (index + (width * (height - 1U) * (bit_pixel / 8U)));

    /* Convert picture to ARGB8888 pixel format */
    for (index = 0; index < height; index++)
    {
      /* Pixel format conversion */
      (void)LCD_ConvertLineToARGB8888((uint32_t *)pbmp_tmp, (uint32_t *)Address, width, InputColorMode);

      /* Increment the source and destination buffers */
      Address += PIXEL_PER_LINE * BYTE_PER_PIXEL;
      pbmp_tmp -= width * (bit_pixel / 8U);
    }
  }

  return status;
}

/**
  * @brief  Fill rectangle with RGB buffer.
  * @param  Instance LCD Instance.
  * @param  Xpos X position on LCD.
  * @param  Ypos Y position on LCD.
  * @param  pData Pointer on RGB pixels buffer.
  * @param  Width Width of the rectangle.
  * @param  Height Height of the rectangle.
  * @retval BSP status.
  */
int32_t BSP_LCD_FillRGBRect(uint32_t Instance, uint32_t Xpos, uint32_t Ypos, uint8_t *pData, uint32_t Width,
                            uint32_t Height)
{
  int32_t  status = BSP_ERROR_NONE;
  uint32_t Xaddress;
  uint32_t StartAddress;
  uint32_t i;
  uint32_t j;

  if (Instance >= LCD_INSTANCES_NBR)
  {
    status = BSP_ERROR_WRONG_PARAM;
  }
  else
  {
    /* Set the start address */
    StartAddress = (hlcd_ltdc.LayerCfg[0].FBStartAdress + (4U * ((Ypos * PIXEL_PER_LINE) + Xpos)));


    /* Fill the rectangle */
    for (i = 0; i < Height; i++)
    {
      Xaddress = StartAddress + (3072U * i);
      for (j = 0; j < Width; j++)
      {
        *(__IO uint32_t *)(Xaddress) = *(uint32_t *)(pData + (4U * j));
        Xaddress += 4U;
      }
    }
  }

  return status;
}

