  hgfxmmu->Init.Buffers.Buf1Address               = 0;
  hgfxmmu->Init.Buffers.Buf2Address               = 0;
  hgfxmmu->Init.Buffers.Buf3Address               = 0;
#if defined (GFXMMU_CR_CE)
