  hgfxmmu->Init.CachePrefetch.OutterCachability   = GFXMMU_OUTTER_CACHABILITY_DISABLE;
  hgfxmmu->Init.CachePrefetch.Prefetch            = GFXMMU_PREFETCH_DISABLE;
